// @ts-nocheck
export const code = async (inputs) => {
  let parsed = {"Vendor_Name": "", "Vendor_GSTIN": "", "Bill_No": "", "Bill_Date": "", "Taxable_Value": 0, "GST_Rate": 0, "CGST": 0, "SGST": 0, "IGST": 0, "Total_Amount": 0, "Narration": "", "Tally_Ledger": "", "Expense_Head": "", "AI_Confidence": 0};
  try { const clean = String(inputs.ai_output).replace(/```json\s*/g,'').replace(/```\s*/g,'').trim(); const m = clean.match(/\{[\s\S]*\}/); parsed = { ...parsed, ...JSON.parse(m ? m[0] : clean) }; } catch (e) { parsed._parse_error = 'true'; }
  const build = async (inputs) => {
  const C = inputs.C, p = inputs.b || {}, r = parsed || {};
  const allowed = ["Bill_ID", "Uploaded_At", "Centre", "Centre_Coordinator", "Bill_Photo", "Vendor_Name", "Vendor_GSTIN", "Bill_No", "Bill_Date", "Taxable_Value", "GST_Rate", "CGST", "SGST", "IGST", "Total_Amount", "Narration", "Tally_Ledger", "Expense_Head", "AI_Confidence", "Status", "Query_From", "Query_Remarks", "Query_Reply", "Accounts_Remarks", "Exported_At"]; const fills = {"Status": "At Centre", "Uploaded_At": "now"};
  const title = (s) => s.replace(/(^|_)(\w)/g, (m, a, b) => a + b.toUpperCase());
  const row = {}; for (const k of allowed) { if (p[k] !== undefined) row[k] = p[k]; else if (r[k] !== undefined) row[k] = r[k]; else if (r[k.toLowerCase()] !== undefined) row[k] = r[k.toLowerCase()]; }
  for (const k of Object.keys(r)) { const t = title(k); if (allowed.includes(t) && row[t] === undefined) row[t] = Array.isArray(r[k]) ? r[k].join('; ') : r[k]; }
  for (const [k, v] of Object.entries(fills)) row[k] = v === 'now' ? new Date().toISOString() : v;
  row['Bill_ID'] = '';   // the app numbers it
  row['Uploaded_At'] = row['Uploaded_At'] || new Date().toISOString();
  for (const k of allowed) if (row[k] === undefined) row[k] = '';
  return { row };
};
  const out = await build(inputs);
  return { ...out, result: parsed };
};
